const waiting = ['browser', 'music', 'editor'];
for (const name of waiting) {
  console.log('CPU -> ' + name);
}

function touchHardware(who) {
  if (who === 'kernel') {
    console.log('hardware accessed');
  } else {
    console.log('DENIED: ' + who + ' stays in user space');
  }
}
touchHardware('my-app');
touchHardware('kernel');

